        "【重要 · 两条独立的线】\n"
        "- 属性问「本性」，位置问「锚点是否已触及它」，两者没有固定关系。\n"
        "- 判的是「锚点有没有碰到它」，不是「你有没有把它列出来」。\n"
        "  被列出来是候选的宿命，不是显形的证据。\n"
        "- 属性与位置一致是常态，不一致才是 &。\n"
